<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {session,logout,clearSession,ApiError} from '../auth'
const router=useRouter(),menuOpen=ref(false),orders=ref<any[]>([]),nextCursor=ref<string|null>(null),loaded=ref(false),message=ref(''),pendingCancel=ref<string|null>(null),recoveryId=ref<string|null>(null),candidates=ref<any[]>([]),fillOrder=ref<string|null>(null),fills=ref<any[]>([]),fillsTruncated=ref(false),attachId=ref(''),ack=ref(false)
const combos=ref<any[]>([]),comboCursor=ref<string|null>(null),comboLoaded=ref(false),comboError=ref(''),comboBusy=ref(false)
async function api(path:string,options:RequestInit={}){const r=await fetch('/api/v1'+path,{credentials:'same-origin',cache:'no-store',...options});const b=await r.json();if(!r.ok)throw new Error(b?.error?.message||'请求失败');return b.data}
async function loadCombos(append=false){if(comboBusy.value)return;comboBusy.value=true;comboError.value='';try{const q=new URLSearchParams({limit:'20',state:'confirmed'});if(append&&comboCursor.value)q.set('cursor',comboCursor.value);const data=await api('/combo-rfqs?'+q);combos.value=append?[...combos.value,...data.items]:data.items;comboCursor.value=data.next_cursor||null;comboLoaded.value=true}catch{comboError.value='组合记录加载失败，请重试。'}finally{comboBusy.value=false}}
const comboState=(s:string)=>({requesting:'询价中',quoted:'已报价，未确认成交',accepting:'确认中',executing:'执行中，未确认成交',confirmed:'已确认',expired:'报价已过期',rejected:'已拒绝',failed:'未成交',unknown:'结果未知'} as Record<string,string>)[s]||'状态未知'
const watchName=(s:string|null)=>({active:'已关注',completed:'已完赛，停止查询'} as Record<string,string>)[s||'']||'未关注'
const bindingName=(s:string|null)=>({pending:'等待匹配',needs_review:'待确认绑定',bound:'已绑定',failed:'绑定失败'} as Record<string,string>)[s||'']||'未绑定'
async function load(append=false){try{const q=new URLSearchParams({limit:'20'});if(append && nextCursor.value)q.set('cursor',nextCursor.value);const data=await api('/trade-intents?'+q);orders.value=append?[...orders.value,...data.items]:data.items;nextCursor.value=data.next_cursor;loaded.value=true}catch{message.value='订单状态加载失败。'}}
const stateName=(s:string)=>({submitting:'提交中',pending:'已接受，待核对',partially_filled:'部分成交',filled:'全部成交',rejected:'已拒绝',cancelled:'已撤单',unknown:'结果未知'} as Record<string,string>)[s]||'未知'
const cancelName=(s:string)=>({submitting:'撤单中',unknown:'撤单结果未知',confirmed:'已确认撤单',rejected:'撤单被拒绝'} as Record<string,string>)[s]||'未知'
async function action(id:string,kind:'cancel'|'reconcile'){try{await api(kind==='cancel'?'/single-orders/'+id+'/cancel':'/trade-intents/'+id+'/reconcile',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:'{}'});pendingCancel.value=null;message.value=kind==='cancel'?'撤单请求已处理，请查看状态。':'已安排只读对账。';await load()}catch{message.value='请求结果未确认，请刷新或安排只读对账。'}}
async function loadFills(id:string){try{const data=await api('/trade-intents/'+id+'/fills');fillOrder.value=id;fills.value=data.items;fillsTruncated.value=data.truncated;message.value='已查询交易所成交记录。'}catch(e){message.value=e instanceof Error?e.message:'成交记录查询失败。'}}
const resolutionOrder=ref<string|null>(null), resolution=ref<any>(null)
async function loadResolution(id:string){try{resolution.value=await api('/trade-intents/'+id+'/resolution');resolutionOrder.value=id}catch(e){message.value=e instanceof Error?e.message:'结算查询失败'}}
async function findCandidates(id:string){recoveryId.value=id;candidates.value=[];attachId.value='';ack.value=false;try{const data=await api('/trade-intents/'+id+'/reconcile-candidates');candidates.value=data.items;message.value=data.truncated?'候选可能不完整，请到 Polymarket 独立核查。':'候选仅包括未完成订单；请独立核实。'}catch{message.value='候选订单查询失败，请稍后重试。'}}
async function attach(){if(!recoveryId.value||!ack.value)return;try{await api('/trade-intents/'+recoveryId.value+'/attach-order',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:JSON.stringify({order_id:attachId.value,acknowledge_uncertainty:true})});message.value='订单编号已关联，状态仍需只读对账。';recoveryId.value=null;await load()}catch(e){message.value=e instanceof Error?e.message:'订单编号关联失败。'}}
async function signOut(){try{await logout();await router.replace('/login')}catch(e){if(e instanceof ApiError&&e.status===401){clearSession();await router.replace('/login')}else message.value='退出请求未确认，请重试。'}}
onMounted(()=>{load();loadCombos()})
</script>
<template><div class="app-layout"><header class="mobile-header"><div class="brand"><span class="brand-mark">P</span> PolySports</div><button class="menu-button" :aria-expanded="menuOpen" aria-controls="primary-nav" @click="menuOpen=!menuOpen">菜单</button></header><aside id="primary-nav" class="sidebar" :class="{open:menuOpen}"><div class="brand sidebar-brand"><span class="brand-mark">P</span> PolySports</div><p class="nav-label">工作台</p><nav aria-label="主导航"><RouterLink to="/">总览</RouterLink><RouterLink to="/sports/football">足球赛事</RouterLink><RouterLink to="/sports/nba">NBA 赛事</RouterLink><RouterLink to="/combos">组合交易</RouterLink><RouterLink to="/orders">交易记录</RouterLink><RouterLink to="/history">历史与导出</RouterLink><RouterLink to="/wallets">钱包状态</RouterLink><RouterLink to="/system">系统管理</RouterLink></nav></aside><main class="workspace order-history"><div class="workspace-top"><span class="breadcrumb">工作台 / 交易记录</span><div class="account"><span>{{session.username}}</span><button class="text-button" @click="signOut">退出</button></div></div><div class="page-heading"><div><p class="eyebrow">ORDER STATUS</p><h1>交易记录</h1><p class="muted">已接受不等于已成交；未知状态须对账，不能重复提交。</p></div></div><p role="status" class="form-message">{{message}}</p><button class="text-button" @click="load()">刷新订单</button><section class="welcome-card"><h2>单场订单</h2><p v-if="loaded && !orders.length">暂无已记录订单。</p><article v-for="order in orders" :key="order.id" class="market-card order-card"><h2>{{order.side==='BUY'?'买入':'卖出'}} · {{stateName(order.state)}}</h2><p>{{order.home}} 对 {{order.away}} · {{order.market_question}} · {{order.outcome_label}}</p><p>限价 {{order.limit_price}} · 份额 {{order.size}} · 已成交 {{order.matched_size ?? '未知'}}</p><p class="id-text">交易所订单 ID：{{order.external_order_id || '未知'}}</p><p v-if="order.error_code">状态说明：{{order.error_code}}<span v-if="order.retry_after_seconds!==null"> · 建议等待 {{order.retry_after_seconds}} 秒</span></p><p v-if="order.cancel_state">撤单状态：{{cancelName(order.cancel_state)}}</p><RouterLink v-if="order.side==='BUY' && Number(order.matched_size)>0" class="text-button" :to="{path:'/orders/new/'+order.market_link_id+'/'+order.outcome_id,query:{close:order.id}}">立即平仓</RouterLink><button v-else class="text-button" disabled title="该记录没有已确认的买入持仓可供平仓">立即平仓</button><button v-if="order.external_order_id" class="text-button" @click="loadFills(order.id)">查询成交记录</button><div v-if="fillOrder===order.id"><p>成交状态由交易所提供，未确认状态不等于结算完成。</p><p v-if="!fills.length">当前查询未返回成交记录。</p><p v-if="fillsTruncated">结果可能不完整，请到交易所核查。</p><p v-for="fill in fills" :key="fill.trade_id" class="id-text">{{fill.trade_id}} · {{fill.size}} 份 · 价格 {{fill.price}} · {{fill.status}}</p></div><button class="text-button" @click="loadResolution(order.id)">核对赛果和市场结算</button><div v-if="resolutionOrder===order.id"><p v-if="resolution?.score_verified">外部赛果：{{resolution.home_score}} : {{resolution.away_score}}</p><p v-else>外部赛果尚未确认。</p><p v-if="resolution?.state==='resolved'">市场选项：{{resolution.outcome_won ? '获胜' : '未获胜'}}。该结果不代表实际盈亏，卖出订单尤其需结合成交与持仓核算。</p><p v-if="resolution?.state==='resolved'">比分核对：{{resolution.score_consistency==='consistent' ? '与市场结果一致' : resolution.score_consistency==='conflict' ? '与市场结果不一致，请人工核实' : '当前市场规则需人工核实'}}</p><p v-else>结算待核实；订单未成交或赛果未确认时不会判定输赢。</p></div><button class="text-button" @click="action(order.id,'reconcile')">安排只读对账</button><button v-if="order.state==='unknown' && !order.external_order_id" class="text-button" @click="findCandidates(order.id)">查找相似未完成订单</button><div v-if="recoveryId===order.id" class="mapping-confirm"><p>候选仅按参数筛选，不证明属于本次提交。请到 Polymarket 独立核对订单编号；未出现不代表订单不存在。</p><p v-for="candidate in candidates" :key="candidate.order_id" class="id-text">{{candidate.order_id}} · {{candidate.created_at}} · {{candidate.status}}</p><label :for="'attach-'+order.id">经独立核实的交易所订单 ID</label><input :id="'attach-'+order.id" v-model="attachId" placeholder="0x…" maxlength="66"><label><input v-model="ack" type="checkbox">我已独立核实该编号属于本次订单</label><button class="text-button" :disabled="!ack || !attachId" @click="attach">关联并继续只读对账</button></div><button v-if="order.external_order_id && ['pending','partially_filled','unknown'].includes(order.state) && (!order.cancel_state || order.cancel_state==='rejected')" class="text-button" @click="pendingCancel=order.id">撤单</button><div v-if="pendingCancel===order.id"><p>确认向交易所撤销此订单？</p><button class="text-button" @click="pendingCancel=null">返回</button><button class="text-button" @click="action(order.id,'cancel')">确认撤单</button></div></article><button v-if="nextCursor" class="text-button" @click="load(true)">加载更多</button></section><section class="welcome-card" aria-label="组合交易记录"><h2>组合交易</h2><p>这里只显示已确认的组合交易；其他询价可在组合记录中查看。</p><button class="text-button" :disabled="comboBusy" @click="loadCombos()">刷新组合记录</button><p v-if="comboError" role="alert">{{comboError}}</p><p v-else-if="comboLoaded && !combos.length">暂无已确认组合交易。</p><article v-for="combo in combos" :key="combo.id" class="market-card order-card"><h3>组合{{combo.direction==='BUY'?'买入':'卖出'}} · {{comboState(combo.state)}}</h3><div v-for="leg in combo.legs" :key="leg.outcome_id"><p>{{leg.home}} 对 {{leg.away}} · {{leg.market_question}} · {{leg.outcome_label}} · {{new Date(leg.starts_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} UTC+8</p><p>比分追踪：{{watchName(leg.watch_state)}} · 外部赛果：{{bindingName(leg.binding_state)}}<span v-if="leg.home_score != null && leg.away_score != null"> · 当前比分：{{leg.home_score}} : {{leg.away_score}}</span><span v-else> · 比分待查询</span><span v-if="leg.next_poll_at"> · 下次查询：{{new Date(leg.next_poll_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}} UTC+8</span></p><RouterLink v-if="leg.sport==='football' || leg.sport==='nba'" :to="'/sports/'+leg.sport">前往赛事中心核对</RouterLink></div><p>预算或份额：{{combo.quantity}} · 钱包：{{combo.wallet_address}}</p><p v-if="combo.quote">询价价格：{{combo.quote.price}} · 报价所需：{{combo.quote.total_required}} · 报价预计{{combo.direction==='BUY'?'份额':'收入'}}：{{combo.quote.net_receive ?? '未知'}}</p><p class="id-text">组合 RFQ：{{combo.external_rfq_id || '未知'}}</p><p v-if="combo.tx_hash" class="id-text">交易哈希：{{combo.tx_hash}}</p><p v-if="combo.error_code">状态说明：{{combo.error_code}}</p><RouterLink v-if="combo.direction==='BUY' && combo.state==='confirmed'" class="text-button" :to="{path:'/combos',query:{close:combo.id}}">立即平仓</RouterLink><button v-else class="text-button" disabled title="该记录不是已确认的组合买入">立即平仓</button><RouterLink to="/combos">查看组合记录</RouterLink></article><button v-if="comboCursor" class="text-button" :disabled="comboBusy" @click="loadCombos(true)">加载更多组合</button></section></main></div></template>
